        ["YMM4EffectShapes.IlluminationPlugin"] = "自然・季節・和風 illumination ひかり light 輝き pattern 模様 柄 木や壁に飾る電飾が、またたきパターンを変えて光る",
        ["YMM4EffectShapes.WagaraPlugin"] = "自然・季節・和風 wagara なみ wave 海 うみ sea ocean 波 は 葉っぱ leaf はいけい background バック もよう pattern 柄 青海波、麻の葉、七宝、市松などのくり返し模様",
