        ["YMM4EffectShapes.MoonPhasePlugin"] = "自然・季節・和風 moon phase ひかり light 輝き つき 月相の変化と、リング状に光る皆既日食",
        ["YMM4EffectShapes.StepProgressPlugin"] = "動画制作・UI step progress ひょう table 一覧 まる circle 円 せん line 「Step1→2→3」を線と丸でつなぎ、順に点灯する。手順の解説に",
        ["YMM4EffectShapes.StickyNotePlugin"] = "動画制作・UI sticky note かぜ wind かみ paper 貼り紙風の飾り。ちぎった紙、斜めに貼ったテープ、画びょうを重ねる",
        ["YMM4EffectShapes.DividerPlugin"] = "動画制作・UI divider はな flower みだし heading タイトル せん line 見出しの下線、花形の罫線、両端が飾りの線など。場面の区切りに",
        ["YMM4EffectShapes.ScreenFramePlugin"] = "動画制作・UI screen frame game げーむ 枠 がめん tv television film 映画 まど window ブラウン管テレビ、ポラロイド、フィルムのコマ、ゲーム機の画面などの額縁。 中央の窓は透明なので、下のレイヤーの映像がのぞきます",
        ["YMM4EffectShapes.WarningPlugin"] = "動画制作・UI warning かぜ wind ひょう table 一覧 せん line 黄黒の斜線帯と点滅するマーク。WARNING 風の演出",
        ["YMM4EffectShapes.RankingBadgePlugin"] = "動画制作・UI ranking badge 順位 じゅんい medal 1位から3位のメダル、リボン、数字がせり上がる",
        ["YMM4EffectShapes.GameUiPlugin"] = "動画制作・UI game ui heart 好き 恋 love げーむ frame 枠 ハートの残機、スコアの数字、コンボのカウンター。 値はキーフレームで動かせます（減った・増えた瞬間に反応します）",
        ["YMM4EffectShapes.ShinePlugin"] = "動画制作・UI shine ひかり light 輝き もじ text テキスト logo 斜めの光の帯が通り過ぎる。ロゴや文字の上に重ねて強調に",
        ["YMM4EffectShapes.LevelUpPlugin"] = "ゲーム・アクション level up ひかり light 輝き ひょう table 一覧 もじ text テキスト 足元の輪から光の柱が立ち、LEVEL UP の文字が弾んで出る",
        ["YMM4EffectShapes.TreasureChestPlugin"] = "ゲーム・アクション treasure chest ひかり light 輝き たからばこ ガタガタ揺れたあとフタが開き、光と金貨があふれ出す",
        ["YMM4EffectShapes.GachaPlugin"] = "ゲーム・アクション gacha ほし star キラキラ ひかり light 輝き 光る玉がふるえ、割れて、レア度に応じた色の光と星が出る",
        ["YMM4EffectShapes.DizzyPlugin"] = "ゲーム・アクション dizzy ほし star キラキラ 頭の上を星やひよこがくるくる回る",
        ["YMM4EffectShapes.MoneyRainPlugin"] = "ゲーム・アクション money rain おかね コイン くるくる回る金貨と、ひらひら舞うお札が降ってくる（特定の通貨ではない絵柄）",
        ["YMM4EffectShapes.PixelArtPlugin"] = "ゲーム・アクション pixel art かぜ wind ばくはつ explosion 爆破 ドカン heart 好き 恋 love coin お金 カクカク動く爆発・ハート・コイン",
        ["YMM4EffectShapes.NamePlatePlugin"] = "解説動画向け name plate item ゲーム 入手 もじ text テキスト 文字 キャラクター character 人物 キャラ名がスッと出る帯。名前の文字は、上に YMM4 のテキストを重ねてください。 アイテムの終わりに自動で引っこむ",
        ["YMM4EffectShapes.ChapterCardPlugin"] = "解説動画向け chapter card text 文字 title 見出し みだし heading タイトル わく frame フレーム がめん screen ほん book 「CHAPTER 1」と見出しの枠が出る、場面の区切り用の画面。 日本語の見出し（「第1章 ○○」など）は、上に YMM4 のテキストを重ねてください",
        ["YMM4EffectShapes.VsScreenPlugin"] = "解説動画向け vs screen がめん キャラクター character 人物 画面を斜めに二分割し、真ん中に「VS」と稲妻。 左右の半分は不透明度を下げると、下に置いた画像やキャラが見える",
        ["YMM4EffectShapes.TimelinePlugin"] = "解説動画向け timeline ひょう table 一覧 text 文字 せん line 横線に年号の点が順に打たれていく。出来事の説明は YMM4 のテキストを重ねてください",
        ["YMM4EffectShapes.MapRoutePlugin"] = "解説動画向け map route ちず せん line ピンが落ちて、点線のルートが次のピンへ伸びていく。下に地図の画像を置いて使える",
        ["YMM4EffectShapes.ChecklistPlugin"] = "解説動画向け checklist もじ text テキスト 文字 項目のチェック欄に、順番にチェックが入る。項目の文字は YMM4 のテキストを重ねてください",
        ["YMM4EffectShapes.BoardBgPlugin"] = "解説動画向け board bg もじ text テキスト はいけい background バック 解説の土台になる背景。文字や図は上に重ねてください",
        ["YMM4EffectShapes.ClockHourglassPlugin"] = "解説動画向け clock hourglass すな sand 砂漠 ひょう table 一覧 とけい 時間 時間の経過を見せる。時計は速さを上げると「時間が飛ぶ」表現にも",
        ["YMM4EffectShapes.NewYearPlugin"] = "季節・イベント new year そら sky しょうがつ 新年 つき moon 初日の出、空に揚がる凧、左右の門松",
        ["YMM4EffectShapes.TanabataPlugin"] = "季節・イベント tanabata かぜ wind そら sky よる night 夜空 風にゆれる笹と色とりどりの短冊。天の川の夜空つき",
        ["YMM4EffectShapes.SummerPlugin"] = "季節・イベント summer かぜ wind なつ 風にゆれる風鈴と、ぱたぱたあおぐうちわ",
        ["YMM4EffectShapes.ChristmasPlugin"] = "季節・イベント christmas ゆき snow 冬 天気 xmas 雪だるま、上からぶら下がるオーナメント、降る雪",
        ["YMM4EffectShapes.MirrorBallPlugin"] = "季節・イベント mirror ball ひかり light 輝き spotlight 照明 ライト 光 回るミラーボールと飛び回る光の粒、首を振るスポットライト",
        ["YMM4EffectShapes.SpeechBubblePlugin"] = "解説動画向け speech bubble ふきだし セリフ 会話 balloon がめん screen セリフの長さに合わせて、自動で大きさが変わる。しっぽの先は、配置画面のつまみで動かせる",
        ["YMM4EffectShapes.ArrowPlugin"] = "解説動画向け arrow やじるし せん line がめん screen 始点から終点へ、線が伸びていく。始点・終点は配置画面のつまみで動かせる",
        ["YMM4EffectShapes.EncirclePlugin"] = "解説動画向け encircle かぜ wind てがき handwriting まる circle 円 せん line 手書き風に、ぐるっと囲んだり、線を引いたりする強調",
        ["YMM4EffectShapes.AnnotationPlugin"] = "解説動画向け annotation もじ text テキスト せん line 指したい点から線を伸ばし、その先に注釈の文字を出す(図解でよく使う形)",
        ["YMM4EffectShapes.CountUpPlugin"] = "解説動画向け count up はじめの数から、目標の数まで、くるくる増えていく(減らすこともできる)",
