        ["YMM4EffectShapes.RelationshipPlugin"] = "解説動画向け relationship やじるし arrow まる circle 円 せん line 人物(丸)と、それを結ぶ線・矢印・関係のラベル。 関係は「1-2:友達」(線)、「1>2:片思い」(1から2への矢印)、「1<>2:ライバル」(両向き)のように書く",
        ["YMM4EffectShapes.ChoiceWindowPlugin"] = "ゲーム・アクション choice window かぜ wind 「はい/いいえ」などの選択肢と、点滅するカーソル(RPG 風)",
        ["YMM4EffectShapes.NovelWindowPlugin"] = "ゲーム・アクション novel window かぜ wind game げーむ もじ text テキスト 名前の欄と、1文字ずつ出るセリフ、言い終わると点滅する ▼",
        ["YMM4EffectShapes.BossIntroPlugin"] = "ゲーム・アクション boss intro かぜ wind ひょう table 一覧 game げーむ がめん screen 画面を横切る帯が走り込み、大きな名前が反対側から飛び込む(格闘ゲーム風)",
