        ["YMM4EffectShapes.SubscribeButtonPlugin"] = "SNS・配信風 subscribe button UI 登録 youtube とうろく logo マウスのカーソルがやって来てボタンを押し、「登録済み」に変わる。ベル・高評価も押せる。 (特定のサービスのロゴは使わない、汎用のデザイン)",
