        ["YMM4EffectShapes.MagnifierFramePlugin"] = "解説動画向け magnifier frame わく フレーム lens カメラ むし bug insect 虫めがねの枠が現れて、見せたい所を強調する(中は透明)。「値」でレンズの大きさ",
        ["YMM4EffectShapes.BulletListPlugin"] = "解説動画向け bullet list もじ text テキスト まる circle 円 「文字」に1行ずつ。番号の丸と一緒に、上から順にスッと出る。バリエーション2はチェックマーク",
        ["YMM4EffectShapes.DotWorldMapPlugin"] = "解説動画向け dot world map ひかり light 輝き ちず 点で描いた世界地図。ところどころが光る。「数」で光る点の数",
        ["YMM4EffectShapes.CompassPlugin"] = "解説動画向け compass もじ text テキスト 方角の文字がついた方位磁針。針は「値」の向き(0=北、25=東…)を指し、少しゆれて止まる",
        ["YMM4EffectShapes.BossHpBarPlugin"] = "ゲーム・アクション boss hp bar 体力 ゲージ ゲーム がめん screen 画面上の大きなHPバー。「値」が残り、「数」が段の数。減った分は少し遅れて赤く消える",
        ["YMM4EffectShapes.ExpBarPlugin"] = "ゲーム・アクション exp bar level レベルアップ ゲーム けいけんち 経験値がたまり、満タンで「LEVEL UP!」。「数」回だけレベルが上がる",
        ["YMM4EffectShapes.CommandInputPlugin"] = "ゲーム・アクション command input ひかり light 輝き ひょう table 一覧 button UI もじ text テキスト 「文字」に カンマ区切りで「↓,↘,→,P」など。ボタンが順に光って並ぶ",
        ["YMM4EffectShapes.KoTextPlugin"] = "ゲーム・アクション ko text ひょう table 一覧 もじ テキスト がめん screen 「K.O.」がドンと出て画面がゆれる。「文字」で表示を変えられる",
        ["YMM4EffectShapes.StageMapPlugin"] = "ゲーム・アクション stage map まる circle 円 道でつながったステージの丸。「値」までクリア済み、次のステージで旗がゆれる。「数」でステージ数",
        ["YMM4EffectShapes.CardFlipPlugin"] = "ゲーム・アクション card flip ひょう table 一覧 もじ text テキスト 裏向きのカードがくるっとめくれて表が見える。「文字」が表の文字、「数」で枚数",
        ["YMM4EffectShapes.ItemDropPlugin"] = "ゲーム・アクション item drop ひかり light 輝き ゲーム 入手 coin お金 宝石やコインが「数」個ポンと飛び出して、はねて地面に落ちる。光の柱つき",
        ["YMM4EffectShapes.MiniMapPlugin"] = "ゲーム・アクション mini map やじるし arrow しかく rectangle box 箱 せん line radar sf 四角いミニマップ。自分の矢印、「数」個の敵の赤い点、ぐるっと回るレーダー線",
        ["YMM4EffectShapes.TurnOrderPlugin"] = "ゲーム・アクション turn order ひかり light 輝き もじ text テキスト かお face 表情 「文字」にカンマ区切りの名前。顔アイコンが横に並び、先頭が光ってくり上がる",
        ["YMM4EffectShapes.LoadingScreenPlugin"] = "ゲーム・アクション loading screen game げーむ もじ text テキスト がめん 黒い画面に、くるくる回る印と「NOW LOADING...」、下にゲームのヒント(文字)",
        ["YMM4EffectShapes.GameOverPlugin"] = "ゲーム・アクション game over げーむ がめん screen はてな 疑問 question 画面が暗くなり「GAME OVER」。下に CONTINUE? と数が減っていくカウント(「数」から)",
        ["YMM4EffectShapes.ResultStarsPlugin"] = "ゲーム・アクション result stars ほし star キラキラ ひかり light 輝き もじ text テキスト がめん screen 「CLEAR!」と星3つ。「数」個の星が順にドンと光る。下にスコア(文字)",
        ["YMM4EffectShapes.DicePlugin"] = "ゲーム・アクション dice サイコロが転がって止まる。「値」で出る目(1〜6 → 0〜100を6等分)。「数」で個数",
        ["YMM4EffectShapes.DealCardsPlugin"] = "ゲーム・アクション deal cards ひょう table 一覧 山札から「数」枚のカードが手前に飛んで扇形に並ぶ。最後に表になる",
        ["YMM4EffectShapes.MashMeterPlugin"] = "ゲーム・アクション mash meter ゲージ button UI もじ text テキスト びっくり 驚き 「連打！」の文字とボタンがへこみ、メーターがガタガタ上がる。「値」が最後の量",
        ["YMM4EffectShapes.SpecialCutinPlugin"] = "ゲーム・アクション special cutin しゅうちゅうせん 漫画 マンガ 効果線 speed lines ひっさつ 技 もじ text テキスト せん line がめん screen 斜めの帯が画面を横切り、技の名前(文字)が流れる。後ろに集中線",
        ["YMM4EffectShapes.StatusIconsPlugin"] = "ゲーム・アクション status icons もじ text テキスト 毒・まひ・ねむり・やけど・こおり のアイコンが並んでふわふわ。「文字」にカンマ区切りで選ぶ",
        ["YMM4EffectShapes.VideoPlayerUiPlugin"] = "動画制作・UI video player ui ひょう table 一覧 button UI もじ text テキスト title 見出し がめん screen 再生ボタン・シークバー・時間の表示。「値」が再生位置、文字がタイトル",
        ["YMM4EffectShapes.MailReceivedPlugin"] = "動画制作・UI mail received がめん screen 手紙 受信ボックスに新しいメールがスッと入ってくる。1行目が差出人、2行目が件名",
        ["YMM4EffectShapes.DialogBoxPlugin"] = "動画制作・UI dialog box かぜ wind title 見出し pc computer ほん book パソコン風の確認ダイアログ。1行目がタイトル、2行目から本文。「値」が50より上でOKが押される",
        ["YMM4EffectShapes.PcWindowPlugin"] = "動画制作・UI pc window button UI title 見出し わく frame フレーム computer タイトルバーと3つのボタンつきのウィンドウ枠。中は透明なので画像を重ねられる",
        ["YMM4EffectShapes.ClickRipplePlugin"] = "動画制作・UI click ripple なみ wave 海 やじるし arrow 矢印カーソルが動いてきてクリック、波紋が広がる。「数」回クリックする",
        ["YMM4EffectShapes.CodeTypingPlugin"] = "動画制作・UI code typing かぜ wind もじ text テキスト がめん screen エディタ風の画面に、文字が1文字ずつ打ち込まれる。行番号つき。「速さ」で打つ速さ",
        ["YMM4EffectShapes.DownloadProgressPlugin"] = "動画制作・UI download progress ファイル名・進み具合のバー・%・残り時間。「値」で最後の%(初めから伸びる)",
        ["YMM4EffectShapes.PollResultPlugin"] = "SNS・配信風 poll result 1行に「選択肢:票数」。横のバーが伸びて%が出る。一番多いものに印",
        ["YMM4EffectShapes.FollowerCounterPlugin"] = "SNS・配信風 follower counter きらきら sparkle 輝き 光 おいわい 祝福 celebration meter ゲージ もじ text テキスト 数字がパラパラ増え、節目(「値2」×1000人ごと)でお祝いのキラキラ。「文字」に最後の数",
        ["YMM4EffectShapes.StreamWaitingPlugin"] = "SNS・配信風 stream waiting countdown タイマー はいけい background バック もよう pattern 柄 がめん screen 「まもなく配信開始」とカウントダウン(「数」分から)、背景に動く模様",
        ["YMM4EffectShapes.EndCardPlugin"] = "SNS・配信風 end card button UI とうろく subscribe もじ text テキスト まる circle 円 わく frame フレーム がめん screen 動画を置く枠2つと、登録ボタンの丸。「ご視聴ありがとうございました」(文字)",
        ["YMM4EffectShapes.NewsLowerThirdPlugin"] = "SNS・配信風 news lower third かぜ wind じまく 字幕 テロップ subtitle みだし heading タイトル logo がめん screen 画面下の帯。左に局ロゴ風の箱(1行目)、右に見出し(2行目)。帯が左から伸びる",
        ["YMM4EffectShapes.BreakingNewsPlugin"] = "SNS・配信風 breaking news ひかり light 輝き telop 字幕 じまく 文字 もじ text テキスト がめん screen 画面上に「ニュース速報」の帯が出て、文字が右から左へ流れる。ピロンと光る",
        ["YMM4EffectShapes.WeatherForecastPlugin"] = "SNS・配信風 weather forecast あめ rain 雨粒 天気 梅雨 ゆき snow 冬 がめん screen 1行に「地名:天気:気温」(天気は 晴/曇/雨/雪)。地名ごとにマークと気温が並ぶ",
        ["YMM4EffectShapes.ReceiptPlugin"] = "動画制作・UI receipt もじ text テキスト 1行に「品名:金額」。レシートが下へ伸びて、最後に合計。「文字」の1行目が店名",
        ["YMM4EffectShapes.HeartBreakPlugin"] = "キャラの気持ち（漫符） heart break 好き 恋 love ハートがドクンと動いたあと、ギザギザに割れて左右に落ちる",
        ["YMM4EffectShapes.AngerFlamePlugin"] = "キャラの気持ち（漫符） anger flame ほのお fire 火 燃える キャラクター character 人物 いかり 怒 angry 💢 キャラの後ろで赤い炎がメラメラ。「値」で炎の高さ",
        ["YMM4EffectShapes.StarEyesPlugin"] = "キャラの気持ち（漫符） star eyes ほし キラキラ きらきら sparkle 輝き 光 目の位置に2つの星がキラキラ回る。「値」で目の間隔",
        ["YMM4EffectShapes.SpiralEyesPlugin"] = "キャラの気持ち（漫符） spiral eyes 目がぐるぐるのうずまき。目を回した時に。「値」で目の間隔",
        ["YMM4EffectShapes.SweatSplashPlugin"] = "キャラの気持ち（漫符） sweat splash あせ 焦り しずく形の汗が、まわりに勢いよく飛び散る。「数」で汗の数。くり返す",
        ["YMM4EffectShapes.PaleLinesPlugin"] = "キャラの気持ち（漫符） pale lines せん line かお face 表情 顔の上に青い縦線がスーッと下りる。ガーン…という時に",
        ["YMM4EffectShapes.SnotBubblePlugin"] = "キャラの気持ち（漫符） snot bubble 寝ているときの鼻ちょうちん。ふくらんだりしぼんだり。最後にパチンと割れる(バリエーション2)",
        ["YMM4EffectShapes.SoulLeavingPlugin"] = "キャラの気持ち（漫符） soul leaving 白いおばけのような魂が、口からふわ〜っと上へ抜けていく",
        ["YMM4EffectShapes.CupidArrowPlugin"] = "キャラの気持ち（漫符） cupid arrow heart 好き 恋 love 矢が飛んできてハートに刺さり、ハートがドキッとはねる",
        ["YMM4EffectShapes.KiranPlugin"] = "キャラの気持ち（漫符） kiran ひかり light 輝き かがみ mirror 反射 一瞬の強い光のきらめき。決めゼリフの時の歯や眼鏡に",
        ["YMM4EffectShapes.FluffyFlowersPlugin"] = "キャラの気持ち（漫符） fluffy flowers はな flower キャラクター character 人物 キャラのまわりに小さなお花が咲いて、ふわふわゆれる。うれしい・のんびり",
        ["YMM4EffectShapes.ShakeLinesPlugin"] = "キャラの気持ち（漫符） shake lines せん line 左右に「))」のような震えの線がブルブル。こわい・寒い時に。「値」で幅",
        ["YMM4EffectShapes.OnomatopoeiaStampPlugin"] = "キャラの気持ち（漫符） onomatopoeia stamp は 葉っぱ leaf もじ text テキスト 「ドーン」「ゴゴゴ」などの太い文字がドンと出てゆれる。「文字」で言葉、バリエーションで出方",
        ["YMM4EffectShapes.TsukkomiHandPlugin"] = "キャラの気持ち（漫符） tsukkomi hand びっくり 驚き 「なんでやねん！」の手が横からビシッと入り、当たったところに衝撃マーク",
        ["YMM4EffectShapes.RainSplashPlugin"] = "天気 rain splash あめ 雨粒 梅雨 なみ wave 海 がめん screen おうかん crown 1位 画面の下(「値」の高さ)に雨が当たって、小さな王冠や波紋ができる。「数」で量",
        ["YMM4EffectShapes.FrostSpreadPlugin"] = "水・氷 frost spread もよう pattern 柄 がめん screen 画面のふちから、白い霜の模様がピキピキと広がる。「値」でどこまで広がるか",
        ["YMM4EffectShapes.IciclesPlugin"] = "水・氷 icicles みず water がめん screen 画面の上(「値」の高さ)から、つららが垂れて、先から水がポタッと落ちる",
        ["YMM4EffectShapes.RainRadarPlugin"] = "天気 rain radar あめ 雨粒 梅雨 くも cloud 空 かぜ wind ちず map はいけい background バック sf 地図風の背景に、緑→黄→赤の雨雲のかたまりが流れていく",
        ["YMM4EffectShapes.SunriseSunsetPlugin"] = "空・宇宙・風景 sunrise sunset そら sky たいよう sun 日光 ひかり よる night 夜空 せん line 地平線から太陽が上る(バリエーション2で沈む)。空の色も夜→朝に変わる",
        ["YMM4EffectShapes.SeaOfCloudsPlugin"] = "空・宇宙・風景 sea of clouds くも cloud 空 うみ ocean 波 山の頂上から見下ろす雲の海。雲がゆっくり流れ、遠くに山の頭が出る",
        ["YMM4EffectShapes.SusukiFieldPlugin"] = "自然・季節・和風 susuki field かぜ wind がめん screen ほん book 画面の下に、ススキ(バリエーション2は稲穂)が並んで風にゆれる。「数」で本数",
        ["YMM4EffectShapes.SnowPilePlugin"] = "天気 snow pile ゆき 冬 がめん screen 雪が降りながら、画面の下に白い雪がだんだん積もっていく。「値」で最後の高さ",
        ["YMM4EffectShapes.DandelionPlugin"] = "自然・舞うもの dandelion かぜ wind 白い綿毛がふわふわ風に乗って、右上へ流れていく。「数」で量",
        ["YMM4EffectShapes.HydrangeaRainPlugin"] = "自然・季節・和風 hydrangea rain あめ 雨粒 天気 梅雨 はな flower は 葉っぱ leaf 青むらさきのあじさいの花のかたまりと葉っぱ。雨粒がしたたる。梅雨の場面に",
        ["YMM4EffectShapes.SunsetDragonflyPlugin"] = "自然・季節・和風 sunset dragonfly そら sky オレンジの夕焼け空を、赤トンボが「数」匹すいすい飛ぶ",
        ["YMM4EffectShapes.CicadaCloudPlugin"] = "自然・季節・和風 cicada cloud くも 空 そら sky なつ summer もじ text テキスト 青空にもくもくの入道雲。「ミーンミーン」の文字がふるえる。夏の場面に",
        ["YMM4EffectShapes.MilkyWayPlugin"] = "空・宇宙・風景 milky way そら sky よる night 夜空 ほし star キラキラ ながれぼし 流星 meteor 夜空を斜めに横切る天の川。細かい星がまたたき、ときどき流れ星",
        ["YMM4EffectShapes.BeachWavesPlugin"] = "空・宇宙・風景 beach waves すな sand 砂漠 なみ wave 海 うみ sea ocean 波 砂浜に白い波がザザーンと寄せては返す。上は青い海",
        ["YMM4EffectShapes.MountainParallaxPlugin"] = "空・宇宙・風景 mountain parallax scroll 流れる 遠くの山ほどゆっくり動く、何層もの山並み。乗り物で移動している場面に。「数」で層の数",
        ["YMM4EffectShapes.BambooForestPlugin"] = "自然・季節・和風 bamboo forest ひかり light 輝き ほん book まっすぐな竹が何本も並び、ゆっくりゆれる。上から光が差す",
        ["YMM4EffectShapes.WaterfallPlugin"] = "水・氷 waterfall きり fog もや 煙 みず water しぶき splash 上から白い水が落ち、下で水しぶきと霧が立つ。「値」で滝の幅",
        ["YMM4EffectShapes.HanamiPlugin"] = "季節・イベント hanami さくら sakura 春 花びら はな flower はる spring 満開の桜の木。花びらが舞い、根元にレジャーシート。春の場面に",
        ["YMM4EffectShapes.SetsubunPlugin"] = "季節・イベント setsubun もじ text テキスト びっくり 驚き 赤鬼のお面に豆がパラパラ当たる。「鬼は外！」(文字)",
        ["YMM4EffectShapes.HinamatsuriPlugin"] = "季節・イベント hinamatsuri はな flower 赤いひな段に、おだいりさまとおひなさま。桃の花とぼんぼり",
        ["YMM4EffectShapes.KoinoboriPlugin"] = "季節・イベント koinobori かぜ wind ポールにつけたこいのぼりが、風でゆらゆら泳ぐ。「数」で匹数",
        ["YMM4EffectShapes.FestivalLanternsPlugin"] = "季節・イベント festival lanterns ひかり light 輝き なつ summer 横に張ったひもに、赤いちょうちんがずらり。ゆらゆら光る",
        ["YMM4EffectShapes.JugoyaPlugin"] = "季節・イベント jugoya よる night 夜空 つき moon 大きな満月にうさぎのかげ、手前にお団子とススキ",
        ["YMM4EffectShapes.ValentinePlugin"] = "季節・イベント valentine heart 好き 恋 love もじ text テキスト リボンをかけたハートの箱。まわりにハートがふわふわ。「文字」でメッセージ",
        ["YMM4EffectShapes.GraduationEntrancePlugin"] = "季節・イベント graduation entrance さくら sakura 春 花びら はな flower もじ text テキスト 校門と「卒業式」などの看板(文字)。桜の花びらが舞う",
        ["YMM4EffectShapes.BirthdayCakePlugin"] = "お祝い birthday cake ひ fire 炎 ほん book ろうそくの火がゆれるケーキ。「数」でろうそくの本数、バリエーション2で火が消える",
        ["YMM4EffectShapes.WeddingPlugin"] = "お祝い wedding はな flower heart 好き 恋 love 金色の鐘がカランカランとゆれ、白いハトとハートの花びらが舞う",
        ["YMM4EffectShapes.GoldScreenCloudPlugin"] = "自然・季節・和風 gold screen cloud くも 空 かぜ wind しょうがつ 新年 new year はいけい background バック つき moon 金屏風の背景に、めでたい雲(瑞雲)がゆっくり流れる。お正月や祝いの場面に",
        ["YMM4EffectShapes.ToriiPathPlugin"] = "自然・季節・和風 torii path ひ fire 炎 とり bird 奥へ続く参道に、朱色の鳥居がいくつも並び、両わきの灯籠に火がともる",
        ["YMM4EffectShapes.MagicBookPlugin"] = "バトル・魔法 magic book ひかり light 輝き もじ text テキスト まほう 魔法陣 ほん 開いた本から光と文字のかけらが立ちのぼる。ページがパラパラめくれる",
        ["YMM4EffectShapes.RuneCirclePlugin"] = "バトル・魔法 rune circle もじ text テキスト まわる輪の上にルーン文字が並び、内と外で反対に回る。「文字」で文字を変えられる",
        ["YMM4EffectShapes.DragonShadowPlugin"] = "バトル・魔法 dragon shadow そら sky かげ 空を大きなドラゴンの影が、はばたきながら横切る。地面に影も",
        ["YMM4EffectShapes.FairyTrailPlugin"] = "バトル・魔法 fairy trail ひかり light 輝き きらきら sparkle 光 小さな光の玉が8の字に飛び、キラキラの粉の跡を残す",
        ["YMM4EffectShapes.GearWarpPlugin"] = "SF・HUD gear warp そら sky とけい clock 時間 大小の歯車が回る中を、時計の針がぐるぐる。過去や未来へ飛ぶ場面に",
        ["YMM4EffectShapes.SpaceStationPlugin"] = "空・宇宙・風景 space station たいよう sun 日光 ひかり ほし star キラキラ うちゅう 銀河 ぎんが ちきゅう earth 太陽電池パネルを広げた人工衛星が、地球の前をゆっくり回る",
        ["YMM4EffectShapes.MeteorStrikePlugin"] = "空・宇宙・風景 meteor strike ひかり light 輝き 燃える隕石が斜めに落ちてきて、地面でドカンと光る",
        ["YMM4EffectShapes.RingedPlanetPlugin"] = "空・宇宙・風景 ringed planet ほし star キラキラ わくせい しまもようの惑星と、ななめの輪。輪の奥側は惑星にかくれる",
        ["YMM4EffectShapes.RobotBootPlugin"] = "SF・HUD robot boot ひかり light 輝き もじ text テキスト がめん screen 「SYSTEM BOOT」の文字と、チェック項目が次々OKになり、最後に目が光る",
        ["YMM4EffectShapes.WormholePlugin"] = "空・宇宙・風景 wormhole ひかり light 輝き 吸いこまれそうな、ねじれたトンネルの穴。光の筋が中心へ向かって回る",
        ["YMM4EffectShapes.AtomModelPlugin"] = "解説動画向け atom model ほん book まん中の原子核のまわりを、3本の軌道で電子が回る。「数」で電子の数",
        ["YMM4EffectShapes.IsekaiGatePlugin"] = "バトル・魔法 isekai gate うず vortex 回転 ひかり light 輝き 石の門の中が光の渦になり、強い光があふれ出す",
        ["YMM4EffectShapes.StealthShimmerPlugin"] = "SF・HUD stealth shimmer ひかり light 輝き 透明なものがそこにいるような、ゆらゆらした輪郭と光のゆがみ",
        ["YMM4EffectShapes.StarChartPlugin"] = "空・宇宙・風景 star chart ほし キラキラ ひかり light 輝き せん line 星と星を線でつないだ星図。点線の航路が伸びて、目的地の星が光る。「数」で星の数",
        ["YMM4EffectShapes.FilmLightLeakPlugin"] = "画面の質感 film light leak かぜ wind ひかり 輝き がめん screen 映画 画面のはしから、オレンジや赤のぼんやりした光がゆらゆら入る。昔のフィルム風",
        ["YMM4EffectShapes.IrisWipePlugin"] = "画面転換 iris wipe まる circle 円 がめん screen 丸い穴がしぼんで画面が黒くなる(バリエーション2で広がって明ける)。「値」が穴の位置の横",
        ["YMM4EffectShapes.PeepholePlugin"] = "画面の質感 peephole まる circle 円 door 扉 ドアののぞき穴から見たような、丸い視界とゆがんだふち",
        ["YMM4EffectShapes.BinocularsPlugin"] = "画面の質感 binoculars まる circle 円 かがみ mirror 反射 双眼鏡をのぞいた、丸が2つつながった視界。少しゆれる",
        ["YMM4EffectShapes.SecurityCamPlugin"] = "画面の質感 security cam かぜ wind せん line わく frame フレーム がめん screen camera 写真 「REC●」と日付・時刻、カメラ番号、走査線。白黒っぽい監視カメラ風の枠",
        ["YMM4EffectShapes.NightVisionPlugin"] = "画面の質感 night vision かぜ wind がめん screen 画面全体を緑色にして、ざらつきとまるい視界。重ねた映像が暗視ゴーグル風に",
        ["YMM4EffectShapes.ThermalLookPlugin"] = "画面の質感 thermal look かぜ wind graph chart 図表 データ 青→緑→黄→赤の熱っぽい色のもやが、ゆっくり動く。温度の目盛りつき",
        ["YMM4EffectShapes.DreamEdgePlugin"] = "画面の質感 dream edge くも cloud 空 がめん screen 画面のまわりが白くぼんやりして、もこもこ雲のふちがゆれる。回想や夢の場面に",
        ["YMM4EffectShapes.WetLensPlugin"] = "画面の質感 wet lens あめ rain 雨粒 天気 梅雨 みず water カメラ camera 写真 カメラのレンズに水滴がつき、ときどきツーッと流れ落ちる",
        ["YMM4EffectShapes.HalftonePlugin"] = "画面の質感 halftone もよう pattern 柄 アメコミのような、大きさのちがう点の模様。ななめに向かって点が小さくなる",
        ["YMM4EffectShapes.MangaPanelsPlugin"] = "画面の質感 manga panels まんが マンガ comic せん line わく frame フレーム がめん screen 黒い太線で画面を漫画のコマに分ける。バリエーションで割り方が変わる",
        ["YMM4EffectShapes.StageCurtainPlugin"] = "画面転換 stage curtain 赤いひだのある幕が左右に開く(バリエーション2で閉じる)。上に飾り幕",
        ["YMM4EffectShapes.PolaroidFramePlugin"] = "画面の質感 polaroid frame かぜ wind てがき handwriting もじ text テキスト わく フレーム しゃしん photo 白いふちのポラロイド写真。下の余白に手書き風の文字。少しかたむいて置かれる",
        ["YMM4EffectShapes.ScreenTonePlugin"] = "画面の質感 screen tone しゅうちゅうせん 漫画 マンガ 効果線 speed lines まんが comic せん line はいけい background バック 漫画の背景のような、点や線のトーン。バリエーションで 点/斜線/集中線/グラデ点",
        ["YMM4EffectShapes.CheckStripePlugin"] = "画面の質感 check stripe はいけい background バック ゆっくり流れる柄の背景。バリエーションで 市松/ストライプ/ギンガム/ボーダー",
        ["YMM4EffectShapes.PopDotsPlugin"] = "画面の質感 pop dots みず water はいけい background バック カラフルな水玉がふわふわ動く、明るい背景。「数」で水玉の数",
        ["YMM4EffectShapes.SunburstPlugin"] = "画面の質感 sunburst ひかり light 輝き せん line はいけい background バック ほん book 中心からの放射状の光線がゆっくり回る。昭和・ポップな強調背景。「数」で線の本数",
        ["YMM4EffectShapes.WavyGradientPlugin"] = "画面の質感 wavy gradient はいけい background バック グラデ 3色がゆっくりうねって混ざる、なめらかな背景",
        ["YMM4EffectShapes.WireframeFloorPlugin"] = "SF・HUD wireframe floor かぜ wind ひかり light 輝き frame 枠 もよう pattern 柄 80年代風の、奥へ続く光る格子の床と、しま模様の夕日",
        ["YMM4EffectShapes.GridTunnelPlugin"] = "SF・HUD grid tunnel しかく rectangle box 箱 はいけい background バック 四角い格子のトンネルを、奥へ進んでいくような背景",
        ["YMM4EffectShapes.BookshelfPlugin"] = "部屋・街の背景 bookshelf はいけい background バック ほん book 色とりどりの本がぎっしり並んだ本棚の背景。「数」で段の数",
        ["YMM4EffectShapes.CafeWindowPlugin"] = "部屋・街の背景 cafe window あめ rain 雨粒 天気 梅雨 まど 窓の外は雨(バリエーション2で晴れ)、手前のテーブルに湯気の立つコーヒー",
        ["YMM4EffectShapes.TrainPlatformPlugin"] = "部屋・街の背景 train platform もじ text テキスト 屋根と柱のある駅のホーム、黄色い点字ブロック、駅名の看板(文字)",
        ["YMM4EffectShapes.TrainWindowPlugin"] = "部屋・街の背景 train window まど 電車の窓から見た景色。電柱がビュンビュン流れ、遠くの山はゆっくり",
        ["YMM4EffectShapes.AquariumTankPlugin"] = "部屋・街の背景 aquarium tank みず water ひかり light 輝き あわ bubble シャボン すいそう 魚 さかな fish 青い水槽に光の筋がゆれ、魚がすいすい、泡がぷくぷく。「数」で魚の数",
        ["YMM4EffectShapes.ConcertPenlightsPlugin"] = "部屋・街の背景 concert penlights light 照明 光 暗い客席で、たくさんのペンライトがリズムに合わせて左右にふられる",
        ["YMM4EffectShapes.ShrineTemplePlugin"] = "自然・季節・和風 shrine temple よる night 夜空 瓦屋根のお堂と、まわりの木々。バリエーション2で夜(灯りがともる)",
        ["YMM4EffectShapes.LaboratoryPlugin"] = "部屋・街の背景 laboratory ひかり light 輝き はいけい background バック フラスコがぶくぶく、ホワイトボードに数式、光るモニター。科学の解説の背景に",
        ["YMM4EffectShapes.GlobeSpinPlugin"] = "小物・アイコン globe spin ちきゅう earth 台にのった地球儀がくるくる回る。大陸が横に流れて見える",
        ["YMM4EffectShapes.GearSetPlugin"] = "小物・アイコン gear set 大小の歯車がかみ合って回る。しくみ・仕事の場面に。「数」で歯車の数",
        ["YMM4EffectShapes.NotifyBadgePlugin"] = "小物・アイコン notify badge つうち notification お知らせ まる circle 円 アイコンの角につく赤い丸と数字。ポンと出て数が増える。「数」が最後の数",
        ["YMM4EffectShapes.TimeBombPlugin"] = "小物・アイコン time bomb ひ fire 炎 まる circle 円 せん line 導火線に火がついた丸い爆弾。「数」秒から数字が減り、0でドカン",
        ["YMM4EffectShapes.TrafficSignalPlugin"] = "小物・アイコン traffic signal ひかり light 輝き 青→黄→赤と光る信号機。「値」で今の色を固定(0=自動、1〜33青、34〜66黄、67〜赤)。バリエーション2は歩行者用",
        ["YMM4EffectShapes.EnvelopeLetterPlugin"] = "小物・アイコン envelope letter もじ text テキスト てがみ かみ paper 封筒のふたが開いて、中から手紙がスーッと出てくる。手紙に「文字」",
        ["YMM4EffectShapes.PodiumPlugin"] = "小物・アイコン podium ひょう table 一覧 もじ text テキスト 1・2・3位の表彰台が下からせり上がる。「文字」にカンマ区切りで1位,2位,3位の名前",
        ["YMM4EffectShapes.PenSignaturePlugin"] = "小物・アイコン pen signature てがき handwriting もじ text テキスト せん line ペン先が動いて、「文字」が手書きのサインのように書かれていく。下に線",
        ["YMM4EffectShapes.LockOpenPlugin"] = "小物・アイコン lock open ひかり light 輝き 南京錠に鍵がささって回り、カチャッとツルが開く。キラッと光る",
        ["YMM4EffectShapes.GiftBoxPlugin"] = "小物・アイコン gift box ゆき snow 冬 天気 ふぶき blizzard 雪 ひかり light 輝き かみふぶき confetti お祝い かみ paper リボンのかかった箱がガタガタゆれて、ふたがポンと飛び、中から光と紙吹雪",
        ["YMM4EffectShapes.HankoStampPlugin"] = "小物・アイコン hanko stamp もじ text テキスト まる circle 円 かげ shadow ハンコがドンと押されて、赤い丸い印影が残る。「文字」で名前(縦書き)",
        ["YMM4EffectShapes.ScaleNeedlePlugin"] = "小物・アイコン scale needle もじ text テキスト まる circle 円 丸い目盛りの体重計。針がぐるんと回って「値」の位置でゆれて止まる。「文字」で単位",
        ["YMM4EffectShapes.CandleFlamePlugin"] = "小物・アイコン candle flame ほのお fire 火 燃える ほん book ゆらめくろうそくの炎と、まわりの明かり。バリエーション2で燭台つき。「数」で本数",
        ["YMM4EffectShapes.RadarChartPlugin"] = "解説動画向け radar chart sf 1行に「項目:値(0〜100)」。5〜8角形の能力値が、中心から広がる。2つめの系列は「項目:値:値」",
        ["YMM4EffectShapes.NumberLinePlugin"] = "解説動画向け number line もじ text テキスト せん 目盛りの上を点が動く。「値」が点、「値2」までの範囲に色がつく。「文字」に「最小,最大」",
        ["YMM4EffectShapes.FractionPizzaPlugin"] = "解説動画向け fraction pizza もじ text テキスト えん circle 丸 円が「数」等分され、「値」の割合だけピースに色がつく。分数の文字つき",
        ["YMM4EffectShapes.FunctionGraphPlugin"] = "解説動画向け function graph chart 図表 データ せん line 座標軸の上に、直線や放物線がペンで描くように伸びる。バリエーションで式の形",
        ["YMM4EffectShapes.CauseChainPlugin"] = "解説動画向け cause chain やじるし arrow 「原因 → 結果 → 結果」の箱が、矢印でつながりながら順に出る。1行に1つ",
        ["YMM4EffectShapes.ProsConsPlugin"] = "解説動画向け pros cons は 葉っぱ leaf ひょう table 一覧 左に○(メリット)、右に×(デメリット)が順に並んで出る。1行に「+言葉」か「-言葉」",
        ["YMM4EffectShapes.StepStairsPlugin"] = "解説動画向け step stairs もじ text テキスト キャラクター character 人物 段を登っていくキャラの印と、各段の文字。「値」の段まで登る",
        ["YMM4EffectShapes.JigsawPuzzlePlugin"] = "解説動画向け jigsaw puzzle もじ text テキスト ピースが飛んできてはまり、最後に1枚の絵(文字)が完成する。「数」で横のピース数",
        ["YMM4EffectShapes.PopulationPyramidPlugin"] = "解説動画向け population pyramid graph chart 図表 データ ぼうぐらふ bar 左右に伸びる横棒グラフ。1行に「名前:左の値:右の値」",
        ["YMM4EffectShapes.UnitConverterPlugin"] = "解説動画向け unit converter meter ゲージ もじ text テキスト 左右2つのメーターの針が連動して回る。「文字」に「左の単位,右の単位,左の最大,倍率」",
        ["YMM4EffectShapes.GlossaryCardPlugin"] = "解説動画向け glossary card みだし heading タイトル 見出し語・読み・説明の3段のカード。1行目が見出し語、2行目が読み、3行目からが説明",
        ["YMM4EffectShapes.FaqQAPlugin"] = "解説動画向け faq qa ふきだし セリフ 会話 balloon speech Qの吹き出しが出て、少し遅れてAが開く。1行目が質問、2行目からが答え",
        ["YMM4EffectShapes.TreasureMapPlugin"] = "ゲーム・アクション treasure map ちず せん line かみ paper ふるい old 昔 古い紙の地図に、点線の道が伸びて、最後に×印が出る",
        ["YMM4EffectShapes.QuestBannerPlugin"] = "ゲーム・アクション quest banner もじ text テキスト 「QUEST CLEAR」などの帯が、左右から伸びて出る。1行目が大きな文字、2行目がクエスト名",
        ["YMM4EffectShapes.SkillTreePlugin"] = "ゲーム・アクション skill tree ひかり light 輝き まる circle 円 せん line 線でつながった丸が、根元から順に解放されて光る。「数」で段の数、「値」で解放する割合",
        ["YMM4EffectShapes.InventoryPlugin"] = "ゲーム・アクション inventory item ゲーム 入手 もじ text テキスト がめん screen マス目にアイテムのアイコンが並び、選択カーソルが動く。「文字」にカンマ区切りでアイテム名",
        ["YMM4EffectShapes.RouletteWheelPlugin"] = "ゲーム・アクション roulette wheel もじ text テキスト えん circle 丸 色分けされた円盤が回って、「値」で決めた区切りで止まる。「文字」にカンマ区切りで区切りの名前",
        ["YMM4EffectShapes.PuzzleChainPlugin"] = "ゲーム・アクション puzzle chain ひかり light 輝き びっくり 驚き 色の玉が並んだ盤面で、同じ色がそろうと光って消え、「〇連鎖！」と出る",
        ["YMM4EffectShapes.PauseScreenPlugin"] = "ゲーム・アクション pause screen がめん 画面が暗くなって「PAUSE」と、選択肢のメニュー。カーソルが点滅する。2行目からがメニュー",
        ["YMM4EffectShapes.TurnStartPlugin"] = "ゲーム・アクション turn start がめん screen 「YOUR TURN」の帯が、画面を左から右へ横切る",
        ["YMM4EffectShapes.BuffDebuffPlugin"] = "ゲーム・アクション buff debuff もじ text テキスト やじるし arrow キャラクター character 人物 キャラの横で、上向き(強化)や下向き(弱体)の矢印が、上下に流れる。「文字」に効果名",
        ["YMM4EffectShapes.JumpDustPlugin"] = "ゲーム・アクション jump dust すな sand 砂漠 足元に、もくもくの砂ぼこりが左右に広がって消える。くり返す",
        ["YMM4EffectShapes.SuperChatPlugin"] = "SNS・配信風 super chat かぜ wind 名前と金額とメッセージの帯。金額に合わせて帯の色が変わる。1行目が名前、2行目が金額、3行目からがメッセージ",
        ["YMM4EffectShapes.ChatColumnPlugin"] = "SNS・配信風 chat column comment 弾幕 がめん screen 画面の右側に、コメントが下から積み上がっていく。1行に「名前:コメント」",
        ["YMM4EffectShapes.ViewCounterPlugin"] = "SNS・配信風 view counter 再生回数と高評価の数字が、回るように増えていく。1行目が再生回数、2行目が高評価",
        ["YMM4EffectShapes.ShortVideoUiPlugin"] = "SNS・配信風 short video ui かぜ wind button UI like good 高評価 comment 弾幕 がめん screen 縦画面の右側に、いいね・コメント・共有ボタン。下にアカウント名と説明。1行目が名前、2行目から説明",
        ["YMM4EffectShapes.WipeFramePlugin"] = "動画制作・UI wipe frame まる circle 円 わく フレーム がめん screen かお face 表情 切り替え 場面転換 まど window 画面の角に置く、丸か角丸の枠。話す人の顔などを入れる用(中は透明)。名前の札つき",
        ["YMM4EffectShapes.SubtitleBandPlugin"] = "動画制作・UI subtitle band じまく 字幕 テロップ もじ text テキスト はいけい background バック 文字の長さに合わせて伸びる、半透明の帯と字幕。「文字」に字幕",
        ["YMM4EffectShapes.ChapterListPlugin"] = "動画制作・UI chapter list ひかり light 輝き 章の一覧で、今の項目だけが光る。「値」で今の章。1行に1つ",
        ["YMM4EffectShapes.DescriptionArrowPlugin"] = "動画制作・UI description arrow もじ text テキスト やじるし 「詳しくは概要欄へ↓」の文字と、下を指す矢印がぴょこぴょこ動く",
        ["YMM4EffectShapes.IncomingCallPlugin"] = "動画制作・UI incoming call button UI がめん screen smartphone スマートフォン 携帯 名前と「着信中…」、応答・拒否のボタン。アイコンの輪が広がる。1行目が名前",
        ["YMM4EffectShapes.MapCurrentLocationPlugin"] = "動画制作・UI map current location ちず 道の地図の上で、青い点と精度の輪、進む向きの扇。点はゆっくり道を進む",
        ["YMM4EffectShapes.CalendarFlipPlugin"] = "動画制作・UI calendar flip もじ text テキスト 日めくりカレンダーの日付がパラパラ進んで止まる。「文字」に「始めの日,終わりの日」(例: 1,15)",
        ["YMM4EffectShapes.IdeaBulbPlugin"] = "キャラの気持ち（漫符） idea bulb ひかり light 輝き せん line 電球がピカッと光り、まわりに線が飛び出す。ひらめいた時に",
        ["YMM4EffectShapes.MoyamoyaPlugin"] = "キャラの気持ち（漫符） moyamoya うず vortex 回転 灰色のもやが、頭の上でぐるぐる渦を巻く。悩んでいる時に",
        ["YMM4EffectShapes.AngrySteamPlugin"] = "キャラの気持ち（漫符） angry steam 頭のてっぺんから、湯気がシューッと勢いよく出る",
        ["YMM4EffectShapes.HeartEyesPlugin"] = "キャラの気持ち（漫符） heart eyes 好き 恋 love 目の位置に2つのハートがドキドキ脈打つ。「値」で目の間隔",
        ["YMM4EffectShapes.TearyEyesPlugin"] = "キャラの気持ち（漫符） teary eyes ひかり light 輝き なみだ tears 泣く 目のふちに涙がたまって、光がゆれる。「値」で目の間隔",
        ["YMM4EffectShapes.DokidokiPlugin"] = "キャラの気持ち（漫符） dokidoki なみ wave 海 heart 好き 恋 love もじ text テキスト 胸の位置でハートが鼓動して、波紋が広がる。「ドキッ」の文字つき",
        ["YMM4EffectShapes.SighPlugin"] = "キャラの気持ち（漫符） sigh 口から、ふわっと白い息が横に流れて消える",
        ["YMM4EffectShapes.DroolPlugin"] = "キャラの気持ち（漫符） drool きらきら sparkle 輝き 光 口元からよだれがたれて、まわりにキラキラ。おいしそうな時に",
        ["YMM4EffectShapes.ColdSweatLinesPlugin"] = "キャラの気持ち（漫符） cold sweat lines せん line あせ 焦り ほん book こめかみに、斜めの3本線と汗のしずく。ギクッとした時に",
        ["YMM4EffectShapes.ShockThunderPlugin"] = "キャラの気持ち（漫符） shock thunder かみなり lightning 稲妻 いなずま もじ text テキスト はいけい background バック 背景が暗くなって、後ろに稲妻がピシャーンと落ちる。「ガーン」の文字つき",
        ["YMM4EffectShapes.ShowerClearingPlugin"] = "天気 shower clearing あめ rain 雨粒 梅雨 くも cloud 空 ひかり light 輝き 雨が降っていて、だんだん止んで、雲の切れ間から光が差す",
        ["YMM4EffectShapes.WindFlagsPlugin"] = "自然・季節・和風 wind flags かぜ ひもに干した洗濯物(バリエーション2は小さな旗)が、風でひらひらゆれる",
        ["YMM4EffectShapes.StormApproachPlugin"] = "天気 storm approach くも cloud 空 かみなり lightning 稲妻 いなずま そら sky ひかり light 輝き 暗い雲が流れてきて空をおおい、遠くでピカッと光る",
        ["YMM4EffectShapes.AutumnMountainPlugin"] = "自然・季節・和風 autumn mountain もみじ こうよう 秋 葉っぱ は leaf 赤や黄色の木々でおおわれた山と、舞う紅葉の葉っぱ",
        ["YMM4EffectShapes.WinterBreathPlugin"] = "天気 winter breath ふゆ まど window 白い息がふわっと出る。バリエーション2は、窓の結露に指で描いた跡と、しずく",
        ["YMM4EffectShapes.RiverTopViewPlugin"] = "空・宇宙・風景 river top view 上から見た川。両岸の草地と、流れの筋、きらめきが流れていく",
        ["YMM4EffectShapes.TidePoolPlugin"] = "空・宇宙・風景 tide pool みず water なみ wave 海 岩のくぼみの水たまりに、小さな波紋とカニ・ヒトデ",
        ["YMM4EffectShapes.DesertHeatHazePlugin"] = "空・宇宙・風景 desert heat haze すな sand 砂漠 ほのお fire 火 燃える せん line 砂丘と強い日ざし。遠くの地平線がゆらゆらゆれる",
        ["YMM4EffectShapes.NightPaddyFrogPlugin"] = "自然・季節・和風 night paddy frog よる 夜空 みず water もじ text テキスト つき moon 夜の田んぼの水面に月が映り、「ケロケロ」の文字が浮かぶ",
        ["YMM4EffectShapes.StarsCityLightsPlugin"] = "空・宇宙・風景 stars city lights そら sky ほし star キラキラ まち 都市 ビル ひかり light 輝き せん line 地平線の街あかりがオレンジに光り、上は満天の星空",
        ["YMM4EffectShapes.SummerCalendarPlugin"] = "季節・イベント summer calendar くも cloud 空 そら sky なつ もじ text テキスト つき moon 青空に入道雲。手前の日めくりが「8月〇日」と進む。「文字」に「月,始めの日,終わりの日」",
        ["YMM4EffectShapes.SportsDayPlugin"] = "季節・イベント sports day そら sky けむり smoke びっくり 驚き 空に万国旗がはためき、スタートピストルが「パン！」と鳴って煙が出る",
        ["YMM4EffectShapes.NewYearHagoitaPlugin"] = "季節・イベント new year hagoita しょうがつ 新年 つき moon 羽子板と羽根が行ったり来たり。バリエーション2は獅子舞がカチカチ口を動かす",
        ["YMM4EffectShapes.TreeLightUpPlugin"] = "季節・イベント tree light up ほし star キラキラ ひかり 輝き christmas xmas 冬 ツリーの電球が上から順に光っていき、最後にてっぺんの星が輝く",
        ["YMM4EffectShapes.FestivalStallsPlugin"] = "季節・イベント festival stalls そら sky よる night 夜空 ひ fire 炎 はなび fireworks 夏 はな flower 夜空に花火、手前にのれんの屋台がずらり。ちょうちんが灯る",
        ["YMM4EffectShapes.SnowFestivalPlugin"] = "季節・イベント snow festival ゆき 冬 天気 よる night 夜空 雪の積もった夜に、中に灯りのともったかまくら。雪がしんしんと降る",
        ["YMM4EffectShapes.CarnationMothersDayPlugin"] = "お祝い carnation mothers day はな flower heart 好き 恋 love 赤いカーネーションの花束と「ありがとう」のメッセージ。ハートがふわふわ",
        ["YMM4EffectShapes.NewYearCountdownPlugin"] = "お祝い new year countdown ゆき snow 冬 天気 ふぶき blizzard 雪 かみふぶき confetti タイマー かみ paper 「3・2・1」と数字が大きく出て、最後に「HAPPY NEW YEAR」と紙吹雪。「数」から数える",
        ["YMM4EffectShapes.PotionBottlePlugin"] = "バトル・魔法 potion bottle あわ bubble シャボン まる circle 円 丸い瓶の中の液体がゆれて、泡がぷくぷく上がる。「値」で液体の量",
        ["YMM4EffectShapes.WandTrailPlugin"] = "バトル・魔法 wand trail ほし star キラキラ まほう magic 魔法陣 杖がくるっと振られて、先から星の粉が軌跡になって残る",
        ["YMM4EffectShapes.TimeStopPlugin"] = "バトル・魔法 time stop ひょう table 一覧 とけい clock 時間 もじ text テキスト がめん screen 画面の色が抜けて(灰色のベール)、大きな時計の針が止まる。「文字」で表示",
        ["YMM4EffectShapes.TeleportBeamPlugin"] = "SF・HUD teleport beam ひかり light 輝き 上から光の柱が降りてきて、光の粒が舞い上がる。転送される場面に",
        ["YMM4EffectShapes.RobotEyeCloseupPlugin"] = "SF・HUD robot eye closeup ひかり light 輝き かお face 表情 金属の顔のアップで、目に「ウィーン」と光が入る",
        ["YMM4EffectShapes.SpaceCommPlugin"] = "SF・HUD space comm うちゅう 銀河 ぎんが なみ wave 海 もじ text テキスト わく frame フレーム noise ざらざら 砂嵐 がめん screen かお face 表情 はけい waveform 音声 オーディオ ノイズまじりの通信モニター。顔の枠と、声の波形、「通信中」の文字",
        ["YMM4EffectShapes.BarrierDomePlugin"] = "バトル・魔法 barrier dome ひかり light 輝き もよう pattern 柄 六角形の模様のドームが、地面から広がって守る。ときどき模様が光る",
        ["YMM4EffectShapes.SwordClashPlugin"] = "バトル・魔法 sword clash ひ fire 炎 はな flower けん 武器 ほん book 2本の剣がぶつかって、まん中で火花がバチッと散る。くり返す",
        ["YMM4EffectShapes.ShadowClonePlugin"] = "バトル・魔法 shadow clone かげ まん中の人影から、半透明の残像が左右に分かれていく。「数」で分身の数",
        ["YMM4EffectShapes.CardSummonPlugin"] = "バトル・魔法 card summon ひかり light 輝き もじ text テキスト まほう magic 魔法陣 まほうじん circle かいてん rotate spin 魔法陣の上にカードが浮かび上がって回転し、光る。「文字」がカードの名前",
        ["YMM4EffectShapes.ColorFocusLinesPlugin"] = "画面の質感 color focus lines そら sky しゅうちゅうせん 漫画 マンガ 効果線 speed せん line はいけい background バック ほん book 色つきの放射状の集中線が、ゆっくり回る背景。まん中は空く。「数」で線の本数",
        ["YMM4EffectShapes.NeonRainStreetPlugin"] = "部屋・街の背景 neon rain street あめ 雨粒 天気 梅雨 よる night 夜空 まち city 都市 ビル ひかり light 輝き 光る サイバー 夜の街に雨が降り、ネオン看板の光がぬれた路面に長く映る",
        ["YMM4EffectShapes.ClassroomPlugin"] = "部屋・街の背景 classroom もじ text テキスト まど window 黒板と窓と並んだ机の教室。黒板に「文字」を書ける",
        ["YMM4EffectShapes.OfficeDeskPlugin"] = "部屋・街の背景 office desk は 葉っぱ leaf はいけい background バック pc computer まど window 窓のあるオフィスの背景。デスクにパソコン、すみに観葉植物",
        ["YMM4EffectShapes.ConvenienceStoreNightPlugin"] = "部屋・街の背景 convenience store night よる 夜空 ひかり light 輝き まど window 夜の駐車場から見た、明るいコンビニの店先。看板と窓の光",
        ["YMM4EffectShapes.GameCenterPlugin"] = "部屋・街の背景 game center ひかり light 輝き げーむ がめん screen 暗い店内に、画面が光る筐体がずらり。床に光が映る。「数」で筐体の数",
        ["YMM4EffectShapes.InfirmaryRoomPlugin"] = "部屋・街の背景 infirmary room ひかり light 輝き まど window 白い壁とベッド、ゆれる仕切りのカーテン。窓からやわらかい光",
        ["YMM4EffectShapes.FisheyeFramePlugin"] = "画面の質感 fisheye frame ひかり light 輝き わく フレーム lens カメラ さかな fish まるくゆがんだ魚眼レンズのふち。まわりが暗く、ふちに光の反射",
        ["YMM4EffectShapes.TvStaticPlugin"] = "画面の質感 tv static すな sand 砂漠 noise ざらざら 砂嵐 すなあらし ノイズ テレビ television ザーッという砂嵐のノイズ。バリエーション2は、チャンネル番号と縦にゆれる切り替え",
        ["YMM4EffectShapes.NormalCurvePlugin"] = "解説動画向け normal curve 正規分布（ベル曲線） 山の形の曲線。指定した範囲を塗って「全体の68%」などを示す 平均・ばらつき・塗る範囲",
        ["YMM4EffectShapes.HistogramPlugin"] = "解説動画向け histogram ヒストグラム 入れた数のばらつきを、階級ごとの棒で表す 数の並び・階級の幅",
        ["YMM4EffectShapes.BoxPlotPlugin"] = "解説動画向け box plot 箱ひげ図 最小・四分位・中央値・最大を箱と線で並べる。複数の組を比べられる 組ごとの5つの値",
        ["YMM4EffectShapes.WaterfallChartPlugin"] = "解説動画向け waterfall chart ウォーターフォール図 「売上→費用→利益」のように、増えた分・減った分を階段状に積む 項目名と増減の数",
        ["YMM4EffectShapes.FunnelChartPlugin"] = "解説動画向け funnel chart ファネル図（じょうご） 段階ごとに人数が減っていく様子を、下ほど細い帯で示す 段階名と数・減り方の割合表示",
        ["YMM4EffectShapes.HeatmapPlugin"] = "解説動画向け heatmap ヒートマップ マスの色の濃さで大小を示す（曜日×時間など） 行と列の名前・数・色の範囲",
        ["YMM4EffectShapes.RoadmapPlugin"] = "解説動画向け roadmap ロードマップ（道と旗） 曲がりくねった道に旗が立ち、今どこまで進んだかを示す 旗の名前・いまの位置",
        ["YMM4EffectShapes.LeverDiagramPlugin"] = "解説動画向け lever diagram てこ・滑車の図 支点・力点・作用点を印で示し、てこが傾く 支点の位置・おもりの重さ",
        ["YMM4EffectShapes.CircuitDiagramPlugin"] = "解説動画向け circuit diagram 回路図（電池・豆電球） スイッチを入れると電流が流れ、電球がつく 直列・並列・スイッチのオンオフ",
        ["YMM4EffectShapes.ChemEquationPlugin"] = "解説動画向け chem equation 化学反応式 左の物質が矢印を通って右の物質に変わる。小さな数字も正しく下付き 反応式の文字",
        ["YMM4EffectShapes.CellDiagramPlugin"] = "解説動画向け cell diagram 細胞の図 核・ミトコンドリアなどを描き、指した部分に名前を出す 植物・動物・指す部分",
        ["YMM4EffectShapes.BodySilhouettePlugin"] = "解説動画向け body silhouette 人体のシルエット 体の部位を光らせて引き出し線で説明する 光らせる部位・説明の文字",
        ["YMM4EffectShapes.JapanTileMapPlugin"] = "解説動画向け japan tile map 日本地図（都道府県） 都道府県を塗り分けたり、選んだ県を光らせたりする 光らせる県・県ごとの色",
        ["YMM4EffectShapes.WorldClocksPlugin"] = "解説動画向け world clocks 世界の時差（時計が並ぶ） 都市名つきの時計を並べ、同じ瞬間の時刻を見せる 都市と時差・基準の時刻",
        ["YMM4EffectShapes.StrataSectionPlugin"] = "解説動画向け strata section 地層の断面図 色の違う層が積み重なり、化石や断層を入れられる 層の数と名前・断層の有無",
        ["YMM4EffectShapes.SolarOrbitPlugin"] = "解説動画向け solar orbit 太陽系の軌道図 惑星がそれぞれの速さで太陽のまわりを回る 惑星の数・回る速さ・名前表示",
        ["YMM4EffectShapes.HajikiDiagramPlugin"] = "解説動画向け hajiki diagram はじきの図（速さ・時間・道のり） 円を三つに分けたおなじみの図。求めるものを隠せる 隠すもの・数字",
        ["YMM4EffectShapes.WordCardPlugin"] = "解説動画向け word card 単語カード 表に単語、めくると裏に意味が出る。英単語・用語の解説に 表と裏の文字・めくる時刻",
        ["YMM4EffectShapes.KanbanBoardPlugin"] = "解説動画向け kanban board カンバン（やることボード） 「やる」「進行中」「完了」の列を、付箋が移っていく 列の名前・付箋の文字と移る順",
        ["YMM4EffectShapes.KpiCardPlugin"] = "解説動画向け kpi card KPIカード 大きな数字と「前月比 +12%」の矢印、小さな折れ線を一枚に 見出し・数字・増減・推移",
        ["YMM4EffectShapes.BattleLogWindowPlugin"] = "ゲーム・アクション battle log window バトルメッセージ窓 「ゆっくり魔理沙の攻撃！」のような文が1行ずつ流れる戦闘ログ メッセージ（1行に1つ）・送る速さ",
        ["YMM4EffectShapes.CriticalHitPlugin"] = "ゲーム・アクション critical hit クリティカル表示 大きな数字と「CRITICAL!」が弾けて飛び出す ダメージの数・文字",
        ["YMM4EffectShapes.MissDodgePlugin"] = "ゲーム・アクション miss dodge ミス・回避の表示 「MISS」「回避！」がふわっと出て消える 文字・動きの向き",
        ["YMM4EffectShapes.GemStonePlugin"] = "ゲーム・アクション gem stone 宝石・ジェム カットされた宝石が回り、面がキラッと光る 形（丸・ひし形・六角）・色",
        ["YMM4EffectShapes.CoinGainPlugin"] = "ゲーム・アクション coin gain コイン獲得（＋の数が飛ぶ） コインが跳ねて所持金の欄へ吸い込まれ、合計が増える 増える数・もとの所持金",
        ["YMM4EffectShapes.EnemyVanishPlugin"] = "ゲーム・アクション enemy vanish 敵の消滅（光の粒になる） 倒した敵が白く光って、粒になって飛び散る 粒の数・色・散る向き",
        ["YMM4EffectShapes.ExpOrbsPlugin"] = "ゲーム・アクション exp orbs 経験値の玉が吸い込まれる 小さな光の玉がいくつも、キャラの位置へ吸い込まれる 玉の数・吸い込む先",
        ["YMM4EffectShapes.ShopWindowPlugin"] = "ゲーム・アクション shop window ショップ画面 商品名・値段・所持金の並んだお店の窓。カーソルが動く 商品と値段（1行に1つ）・選ぶ行",
        ["YMM4EffectShapes.EquipWindowPlugin"] = "ゲーム・アクション equip window 装備画面 頭・体・武器・盾の枠に装備名が入る 各枠の名前・キャラ名",
        ["YMM4EffectShapes.StatComparePlugin"] = "ゲーム・アクション stat compare ステータスの比較（↑↓） 装備を変えた時の増減を、緑の↑と赤の↓で見せる 項目名と前後の数",
        ["YMM4EffectShapes.DungeonMapPlugin"] = "ゲーム・アクション dungeon map ダンジョンのマップ 部屋が通路でつながり、訪れた部屋が明るくなる 部屋の数・いまの部屋・シード",
        ["YMM4EffectShapes.SavePointPlugin"] = "ゲーム・アクション save point セーブポイント 光る結晶が浮かんで回り、「セーブしました」が出る 色・文字",
        ["YMM4EffectShapes.TargetCursorPlugin"] = "ゲーム・アクション target cursor ターゲット選択の矢印 敵の頭上で上下に揺れる選択カーソル 矢印の形・揺れの大きさ",
        ["YMM4EffectShapes.JustDodgePlugin"] = "ゲーム・アクション just dodge ジャスト回避（JUST!） 画面が青くなって時間がゆっくりになり、「JUST!」が出る 文字・色・長さ",
        ["YMM4EffectShapes.RankResultPlugin"] = "ゲーム・アクション rank result ランク判定（S・A・B） 大きなランクの文字がドンと押され、評価が並ぶ ランク・評価の項目",
        ["YMM4EffectShapes.LoadingTipsPlugin"] = "ゲーム・アクション loading tips ロード中のTips枠 「TIPS」の見出しと、切り替わるひとこと説明 文（1行に1つ）・切り替えの間隔",
        ["YMM4EffectShapes.RhythmNotesPlugin"] = "ゲーム・アクション rhythm notes リズムゲームのノーツ レーンを音符が流れてきて、判定線で「PERFECT」 レーン数・テンポ・譜面のシード",
        ["YMM4EffectShapes.FighterHpBarsPlugin"] = "ゲーム・アクション fighter hp bars 格闘ゲームの体力バー 左右に2人の体力と名前、「ROUND 1 FIGHT!」 2人の名前・体力・ラウンド",
        ["YMM4EffectShapes.MashQtePlugin"] = "ゲーム・アクション mash qte ボタン連打のQTE 「◯ボタンを連打！」と縮む輪。成功・失敗を選べる ボタンの文字・結果",
        ["YMM4EffectShapes.TargetGamePlugin"] = "ゲーム・アクション target game 的あてミニゲーム 的が出たり引っ込んだりし、当たると得点が増える 的の数・得点・シード",
        ["YMM4EffectShapes.MessengerChatPlugin"] = "SNS・配信風 messenger chat メッセージアプリの会話 左右の吹き出しが順に出て、「既読」や「入力中…」も付く 会話（1行に1つ、頭に左右）・速さ",
        ["YMM4EffectShapes.HashtagPopPlugin"] = "SNS・配信風 hashtag pop ハッシュタグが並ぶ 「#ゆっくり実況」などのタグがポンポンと現れる タグの文字・並び方",
        ["YMM4EffectShapes.ProfileCardPlugin"] = "SNS・配信風 profile card プロフィールカード アイコンの丸・名前・自己紹介・フォロワー数のカード 名前・ID・紹介文・数",
        ["YMM4EffectShapes.StoryProgressPlugin"] = "SNS・配信風 story progress ストーリーズ風の進行バー 上に区切られた細いバーがあり、順に満たされていく 区切りの数・名前",
        ["YMM4EffectShapes.ReviewStarsPlugin"] = "SNS・配信風 review stars 口コミの星評価 「★★★★☆ 4.2」とレビュー文。星が左から塗られていく 点数・件数・レビュー文",
        ["YMM4EffectShapes.ProductCardPlugin"] = "SNS・配信風 product card ネットショップの商品カード 商品名・値段・「カートに入れる」ボタン、値引きの印 商品名・値段・値引き率",
        ["YMM4EffectShapes.FakeQrScanPlugin"] = "SNS・配信風 fake qr scan QRコード風の読み取り 四角い模様（本物のQRではない）を線が走って「読み取り完了」 模様のシード・文字",
        ["YMM4EffectShapes.LoginScreenPlugin"] = "SNS・配信風 login screen ログイン画面 IDとパスワードが1文字ずつ打たれ（パスワードは●）、ログインを押す IDの文字・成功か失敗か",
        ["YMM4EffectShapes.ErrorScreenPlugin"] = "SNS・配信風 error screen エラー画面 「404 ページが見つかりません」や、青い停止画面風の表示 種類・文字",
        ["YMM4EffectShapes.FileCopyDialogPlugin"] = "SNS・配信風 file copy dialog ファイルのコピー画面 紙が飛んでいくアニメと、進み具合・残り時間 ファイル名・進み具合",
        ["YMM4EffectShapes.TaskbarNoticePlugin"] = "SNS・配信風 taskbar notice タスクバーと通知アイコン 画面の下にアイコンと時計、通知が出る アイコンの数・時刻・通知文",
        ["YMM4EffectShapes.ContextMenuGuidePlugin"] = "SNS・配信風 context menu guide 右クリックメニューの解説 カーソルが右クリックしてメニューが開き、項目を選ぶ メニュー項目・選ぶ行",
        ["YMM4EffectShapes.VideoCallGridPlugin"] = "SNS・配信風 video call grid ビデオ通話の画面 2〜4分割の枠に名前とマイクの印。話している枠が光る 人数・名前・話す人",
        ["YMM4EffectShapes.RecIndicatorPlugin"] = "SNS・配信風 rec indicator 録画中のRECマーク 赤い点滅と「REC」、進む時間、四隅のカギ線 始まりの時間・電池表示",
        ["YMM4EffectShapes.CommentPickupPlugin"] = "SNS・配信風 comment pickup コメントのピックアップ枠 配信で読み上げるコメントを、名前つきの大きな枠で出す 名前・コメント",
        ["YMM4EffectShapes.TrendRankingPlugin"] = "SNS・配信風 trend ranking トレンドランキング 順位と話題が並び、急上昇の矢印が付く 話題（1行に1つ）・上昇の印",
        ["YMM4EffectShapes.ScreenshotFlashPlugin"] = "SNS・配信風 screenshot flash スクリーンショット 白く光って画面が小さくなり、隅に吸い込まれる 吸い込む向き",
        ["YMM4EffectShapes.CalendarAppPlugin"] = "SNS・配信風 calendar app カレンダーアプリの予定 月の表の日付に印と予定の帯が入る 年月・予定（日付と名前）",
        ["YMM4EffectShapes.CalculatorScreenPlugin"] = "SNS・配信風 calculator screen 電卓の画面 数字が打たれて、最後に答えが出る 式・答え・打つ速さ",
        ["YMM4EffectShapes.NaviTurnPlugin"] = "SNS・配信風 navi turn ナビの曲がる案内 「300m先 右方向」の矢印と道の図 向き・距離・通りの名前",
        ["YMM4EffectShapes.SleepyZzzPlugin"] = "キャラの気持ち（漫符） sleepy zzz Zzz（眠い・寝ている） 「Z」が大きくなりながらゆらゆら浮かんでいく 文字の数・浮かぶ向き",
        ["YMM4EffectShapes.StartleLinesPlugin"] = "キャラの気持ち（漫符） startle lines ビクッ（驚きの跳ね線） 体のまわりに短い線がパッと出て、全体が小さく跳ねる 線の数・跳ねる高さ",
        ["YMM4EffectShapes.ChiinBellPlugin"] = "キャラの気持ち（漫符） chiin bell ちーん（鐘と線香） 「ちーん」の文字とおりん、線香の煙。やらかした時に 文字・煙の量",
        ["YMM4EffectShapes.SmirkShadowPlugin"] = "キャラの気持ち（漫符） smirk shadow ニヤリの暗い影 顔の上半分に暗い影が落ち、目だけが光る 影の濃さ・目の色",
