        ["YMM4EffectShapes.CozyTeaPlugin"] = "キャラの気持ち（漫符） cozy tea ほっこり（湯気の立つお茶） 湯のみとゆらゆらの湯気、まわりに丸い暖かい光 湯気の量・光の色",
        ["YMM4EffectShapes.GoosebumpsPlugin"] = "キャラの気持ち（漫符） goosebumps ひえっ（鳥肌） 体のまわりにぶつぶつと細い震え線が広がる ぶつぶつの量・震え",
