        ["YMM4EffectShapes.BlankEyesPlugin"] = "キャラの気持ち（漫符） blank eyes 白目（ショック） 目の位置に白い円を重ねて、魂が抜けたような顔に 目の位置と間隔・大きさ",
        ["YMM4EffectShapes.ShiverColdPlugin"] = "キャラの気持ち（漫符） shiver cold ぶるぶる寒い 青い振動の線と小さな雪、鼻水のつらら 振動の大きさ・雪の量",
        ["YMM4EffectShapes.MuscleFlexPlugin"] = "キャラの気持ち（漫符） muscle flex ムキムキ（力こぶとオーラ） 力こぶのマークと「ムキィッ」、燃えるような輪郭 文字・オーラの色",
        ["YMM4EffectShapes.HungryGuuPlugin"] = "キャラの気持ち（漫符） hungry guu 腹ペコ（ぐぅ〜） 「ぐぅ〜」の文字が波打ち、お腹の位置に渦巻き 文字・渦の位置",
        ["YMM4EffectShapes.GigglePlugin"] = "キャラの気持ち（漫符） giggle くすくす笑い 小さな音符と「くす」の文字が弾む 文字・数",
        ["YMM4EffectShapes.SadRaincloudPlugin"] = "キャラの気持ち（漫符） sad raincloud しょんぼりの雨雲 頭の上だけに小さな雨雲があり、そこだけ雨が降る 雲の大きさ・雨の量・雷",
        ["YMM4EffectShapes.AngryStompPlugin"] = "キャラの気持ち（漫符） angry stomp イライラの足踏み 足元に「トントン」の文字と衝撃の線が繰り返す 速さ・文字",
