        ["YMM4EffectShapes.TyphoonSatellitePlugin"] = "天気 typhoon satellite 台風（衛星写真風） 上から見た雲の渦が回り、中心に「目」がある 大きさ・回る速さ・進む向き",
        ["YMM4EffectShapes.MorningDewPlugin"] = "自然・季節・和風 morning dew 朝露のしずく 葉の上のしずくが光を受けて輝き、ゆっくり流れる しずくの数・葉の色",
        ["YMM4EffectShapes.MossForestFloorPlugin"] = "自然・季節・和風 moss forest floor 苔と森の地面 苔むした岩と地面、小さな光の粒 緑の濃さ・光の量",
        ["YMM4EffectShapes.MushroomForestPlugin"] = "自然・季節・和風 mushroom forest キノコの森 大小のキノコが生え、うっすら光る（幻想的にもできる） 数・光るか・色",
        ["YMM4EffectShapes.JellyfishDriftPlugin"] = "水・氷 jellyfish drift クラゲがただよう 半透明のクラゲがふわふわ上下しながら漂う 数・色・光り方",
        ["YMM4EffectShapes.GoldfishBowlPlugin"] = "水・氷 goldfish bowl 金魚鉢の金魚 丸い鉢の中で金魚が泳ぎ、泡が上がる 金魚の数・水草",
        ["YMM4EffectShapes.WhaleSilhouettePlugin"] = "水・氷 whale silhouette クジラのシルエット 大きなクジラが画面をゆっくり横切る（海・空どちらにも） 向き・速さ・海か空か",
        ["YMM4EffectShapes.OwlNightForestPlugin"] = "自然・季節・和風 owl night forest フクロウの目が光る夜の森 暗い森で、枝のフクロウがまばたきする 数・まばたきの間隔",
        ["YMM4EffectShapes.AntTrailPlugin"] = "自然・季節・和風 ant trail 蟻の行列 小さな蟻が列になって曲がりくねって進む 数・道の曲がり方",
        ["YMM4EffectShapes.DewySpiderWebPlugin"] = "自然・季節・和風 dewy spider web クモの巣（朝露つき） 放射状の巣が中心から張られ、露が光る すき間・露の量",
        ["YMM4EffectShapes.CoralReefPlugin"] = "水・氷 coral reef サンゴ礁 色とりどりのサンゴと小魚、光のゆらぎ 魚の数・水の色",
        ["YMM4EffectShapes.AvalanchePlugin"] = "自然・季節・和風 avalanche 雪崩 山の斜面を白い雪がどどどと流れ落ちる 勢い・向き",
        ["YMM4EffectShapes.GroundCrackPlugin"] = "自然・季節・和風 ground crack 地割れ（地震の亀裂） 地面にひびが走って広がり、砂がこぼれる 割れ始めの位置・本数",
        ["YMM4EffectShapes.HazyMoonPlugin"] = "空・宇宙・風景 hazy moon おぼろ月 月に薄い雲がかかって流れ、光がにじむ 月の形・雲の濃さ",
        ["YMM4EffectShapes.MistyLakePlugin"] = "空・宇宙・風景 misty lake 朝霧の湖（水面に映る） 霧のかかった湖と山、逆さまに映る景色 時間帯・霧の濃さ",
        ["YMM4EffectShapes.SunflowerFieldPlugin"] = "自然・季節・和風 sunflower field ひまわり畑 ひまわりが一面に咲き、風でそろって揺れる 密度・空の色",
        ["YMM4EffectShapes.RollingAcornsPlugin"] = "自然・季節・和風 rolling acorns どんぐりが転がる どんぐりや松ぼっくりが転がってきて止まる 数・転がる向き",
        ["YMM4EffectShapes.SnailOnLeafPlugin"] = "自然・季節・和風 snail on leaf 雨上がりのカタツムリ あじさいの葉の上を、カタツムリがゆっくり進む 進む速さ・向き",
        ["YMM4EffectShapes.ComingOfAgePlugin"] = "季節・イベント coming of age 成人式（振袖と鶴） 紅白の背景に鶴が舞い、「祝 成人」の文字 文字・色の組み合わせ",
        ["YMM4EffectShapes.KabutoDecorPlugin"] = "季節・イベント kabuto decor 端午の節句の兜飾り 兜と菖蒲、こいのぼりとは別の飾り 色・背景の有無",
        ["YMM4EffectShapes.FloatingLanternsPlugin"] = "季節・イベント floating lanterns 灯籠流し 川に灯籠がゆっくり流れ、水面に光が映る 灯籠の数・流れる速さ",
        ["YMM4EffectShapes.BonDanceTowerPlugin"] = "季節・イベント bon dance tower 盆踊りのやぐら やぐらと提灯の列、太鼓の音に合わせて提灯が揺れる 提灯の数・揺れの速さ",
        ["YMM4EffectShapes.ShichiGoSanPlugin"] = "季節・イベント shichi go san 七五三（千歳飴） 千歳飴の袋と鶴亀、「祝 七五三」 文字・色",
        ["YMM4EffectShapes.BigCleaningPlugin"] = "季節・イベント big cleaning 大掃除（ほうきとほこり） ほうきが動いて、ほこりが舞い、きれいになって光る 掃く向き・ほこりの量",
        ["YMM4EffectShapes.NewYearCardPlugin"] = "季節・イベント new year card 年賀状（干支のはんこ） はがきの枠に干支のはんこと「謹賀新年」 干支・文字・年",
        ["YMM4EffectShapes.KagamiMochiPlugin"] = "季節・イベント kagami mochi 鏡餅 二段の餅とみかん、敷き紙 大きさ・飾りの有無",
        ["YMM4EffectShapes.JoyaBellPlugin"] = "季節・イベント joya bell 除夜の鐘 鐘がゆっくり揺れて、音の輪が広がり、回数が増える 鳴らす回数・数字表示",
        ["YMM4EffectShapes.OmikujiPlugin"] = "季節・イベント omikuji おみくじ 筒から棒が出て、紙が開くと「大吉」などが出る 結果・開く時刻",
        ["YMM4EffectShapes.KakizomePlugin"] = "自然・季節・和風 kakizome 書き初め 筆で一画ずつ文字が書かれていく（墨のかすれつき） 文字・書く速さ",
        ["YMM4EffectShapes.DarumaEyesPlugin"] = "自然・季節・和風 daruma eyes だるま（目を入れる） だるまに片目、あとで両目が入る 目の数・色",
        ["YMM4EffectShapes.LuckyCatPlugin"] = "自然・季節・和風 lucky cat 招き猫 手が上下にゆっくり動き、小判が光る 上げる手・色",
        ["YMM4EffectShapes.HanafudaCardsPlugin"] = "自然・季節・和風 hanafuda cards 花札 札がめくれて並ぶ（松に鶴・桜に幕など、絵柄は簡略） 札の種類・並べ方",
        ["YMM4EffectShapes.WagasaRainPlugin"] = "自然・季節・和風 wagasa rain 和傘と雨 赤い番傘が回り、雨が傘ではじける 傘の色・回る速さ",
        ["YMM4EffectShapes.TeaRoomPlugin"] = "自然・季節・和風 tea room 茶室と抹茶 畳・障子・茶碗から湯気、静かな光 湯気の量・時間帯",
        ["YMM4EffectShapes.CrestSymbolPlugin"] = "自然・季節・和風 crest symbol 家紋風のシンボル 円の中に植物や図形を組んだ家紋風の模様（架空の紋） 模様の種類・線の太さ",
        ["YMM4EffectShapes.KabukiMiePlugin"] = "自然・季節・和風 kabuki mie 歌舞伎の見得 隈取りの線と拍子木の文字、黒・柿色・萌葱の幕 隈取りの色・文字",
        ["YMM4EffectShapes.FoldingFanPlugin"] = "自然・季節・和風 folding fan 扇子が開く 扇子がパッと開いて、模様が現れる 模様・開く角度",
        ["YMM4EffectShapes.SantaMoonSleighPlugin"] = "季節・イベント santa moon sleigh サンタのソリが月を横切る 満月の前をトナカイのソリのシルエットが横切る 向き・速さ",
