        ["YMM4EffectShapes.CurseGlyphsPlugin"] = "バトル・魔法 curse glyphs 呪いの紋様が広がる 黒紫の紋様がじわじわと足元から広がる 広がる速さ・色",
        ["YMM4EffectShapes.SealingTalismanPlugin"] = "バトル・魔法 sealing talisman 封印のお札 お札が飛んできて貼りつき、光の鎖で縛られる 札の数・文字",
        ["YMM4EffectShapes.PetrifyPlugin"] = "バトル・魔法 petrify 石化 下から灰色の石の質感が広がり、ひびが入る 進む向き・速さ",
        ["YMM4EffectShapes.TimeRewindPlugin"] = "バトル・魔法 time rewind 時を戻す 時計の針が逆回りし、画面に逆向きの光の筋が走る 針の速さ・色",
