        ["YMM4EffectShapes.FleetBarragePlugin"] = "SF・HUD fleet barrage 宇宙戦艦の砲撃 艦隊のシルエットから光弾が飛び交う 艦の数・弾の色・向き",
        ["YMM4EffectShapes.UfoEscapePlugin"] = "SF・HUD ufo escape UFOが飛び去る 円盤がジグザグに動いて、一瞬で空へ消える 動きの形・光の色",
        ["YMM4EffectShapes.AlienTextFlowPlugin"] = "SF・HUD alien text flow 異星の文字が流れる 読めない記号の文字が横や縦に流れる 向き・密度・色",
        ["YMM4EffectShapes.MechPanelsPlugin"] = "SF・HUD mech panels メカの変形（パネルが開く） 四角い板が次々にがちゃんと開いて、中から光が漏れる 板の数・開く順",
        ["YMM4EffectShapes.PlanetSurfacePlugin"] = "SF・HUD planet surface 惑星の地表（クレーター） 月や火星のような地表と、空に浮かぶ大きな地球 地面の色・空の天体",
        ["YMM4EffectShapes.SpaceHelmetViewPlugin"] = "SF・HUD space helmet view 宇宙服のヘルメット越しの視界 丸いガラスの縁と映り込み、端に酸素の残り表示 酸素の数・曇り",
