        ["YMM4EffectShapes.NanoSwarmPlugin"] = "SF・HUD nano swarm ナノマシンの群れ 細かい点の群れが集まって形（丸・星・文字）になる 粒の数・できる形",
        ["YMM4EffectShapes.DataCubePlugin"] = "SF・HUD data cube データの立方体 光る立方体が回り、面に数字が流れる 大きさ・回る速さ",
        ["YMM4EffectShapes.TarotSpreadPlugin"] = "バトル・魔法 tarot spread タロットカード 裏向きのカードが並び、選んだ一枚が光ってめくれる（絵柄は独自） 枚数・カードの名前",
        ["YMM4EffectShapes.CrystalBallPlugin"] = "バトル・魔法 crystal ball 水晶玉の占い 水晶玉の中で煙が渦巻き、文字や影が浮かぶ 煙の色・浮かぶ文字",
        ["YMM4EffectShapes.AnvilForgePlugin"] = "バトル・魔法 anvil forge 鍛冶の金床と火花 ハンマーが振り下ろされるたびに火花が飛ぶ 打つ回数・火花の量",
        ["YMM4EffectShapes.DoubleDoorPlugin"] = "画面転換 double door 両開きの扉 画面を覆う扉が左右に開いて、次の場面が見える 扉の種類（木・鉄・ふすま）・速さ",
        ["YMM4EffectShapes.RollingShutterPlugin"] = "画面転換 rolling shutter シャッターが閉まる お店のシャッターがガラガラと下りてくる 色・落書きの文字",
        ["YMM4EffectShapes.CubeTurnPlugin"] = "画面転換 cube turn キューブ回転 画面が立方体の面のように回って次の面へ 回る向き・速さ",
        ["YMM4EffectShapes.PaperBallTossPlugin"] = "画面転換 paper ball toss 紙が丸まって飛ぶ 画面がくしゃくしゃに丸まって、ごみ箱へ投げられる 飛ぶ向き・ごみ箱の有無",
        ["YMM4EffectShapes.PuzzleBreakPlugin"] = "画面転換 puzzle break パズルのピースが外れる 画面がピースに分かれ、バラバラに落ちていく ピースの数・落ちる順",
        ["YMM4EffectShapes.ScreenMeltPlugin"] = "画面転換 screen melt 画面が溶ける 上から絵の具のように垂れて溶け落ちる 垂れる本数・色",
        ["YMM4EffectShapes.MirrorSymmetryPlugin"] = "画面転換 mirror symmetry 鏡のシンメトリー 画面の半分を反転して重ね、左右対称にする 向き（左右・上下・4方向）",
        ["YMM4EffectShapes.ClockWipePlugin"] = "画面転換 clock wipe 時計の針ワイプ 中心から時計回りに扇形で塗りつぶす 始まりの角度・向き・縁のぼかし",
        ["YMM4EffectShapes.LightningFlashPlugin"] = "画面転換 lightning flash 落雷の白フラッシュ 一瞬白く光って、人物が黒いシルエットになる 光る回数・長さ",
        ["YMM4EffectShapes.FocusPullPlugin"] = "画面転換 focus pull ピント合わせ ぼやけた丸い枠がだんだんくっきりし、十字の印が重なる 合わせる位置・時間",
        ["YMM4EffectShapes.ScreenCrackPlugin"] = "画面転換 screen crack 画面にひびが入る 衝撃の位置からひびが放射状に広がる（割れない） 中心・ひびの数",
        ["YMM4EffectShapes.CenterSuckPlugin"] = "画面転換 center suck 中心へ吸い込む 放射状にぶれながら中心へ吸い込まれて消える 中心・回転の有無",
        ["YMM4EffectShapes.ColorRipplePlugin"] = "画面転換 color ripple 色の波が広がる 複数の色の円が時間差で広がって画面を覆う 色の数・中心",
        ["YMM4EffectShapes.PhoneSwipePlugin"] = "画面転換 phone swipe スマホのスワイプ 指の印が動いて、画面が横に滑って次へ 向き・指の表示",
        ["YMM4EffectShapes.BubblePopRevealPlugin"] = "画面転換 bubble pop reveal ぽよんと弾けて出る 丸い形がぷくっと膨らんで弾け、中から次の場面 形・色・弾む強さ",
        ["YMM4EffectShapes.WordFloodPlugin"] = "画面転換 word flood 文字で埋まる 入れた言葉がどんどん増えて画面を埋め尽くす 言葉・増える速さ",
        ["YMM4EffectShapes.FireSpreadPlugin"] = "画面転換 fire spread 炎が燃え広がる 下から炎が上がって画面を燃やし、次の場面へ 向き・色",
        ["YMM4EffectShapes.WaterRiseFillPlugin"] = "画面転換 water rise fill 水が満ちる 水位が上がって画面を覆い、泡が上がる 水の色・波の高さ",
        ["YMM4EffectShapes.PaintSplashPlugin"] = "画面転換 paint splash 絵の具のスプラッシュ 絵の具がバシャッと飛び散って画面を塗りつぶす 色の数・飛び散る位置",
        ["YMM4EffectShapes.LightTunnelPlugin"] = "画面転換 light tunnel 光のトンネルを抜ける 光の輪が次々と近づいてきて、最後に白く抜ける 色・輪の形・速さ",
        ["YMM4EffectShapes.LibraryBackPlugin"] = "部屋・街の背景 library back 図書館 高い本棚が奥まで並び、窓から光が差す 時間帯・ぼかし",
        ["YMM4EffectShapes.GymBackPlugin"] = "部屋・街の背景 gym back 体育館 床のライン、バスケットゴール、ギャラリーの窓 時間帯・照明",
        ["YMM4EffectShapes.SchoolRooftopPlugin"] = "部屋・街の背景 school rooftop 学校の屋上 フェンスと広い空、過ぎていく雲 時間帯・雲の速さ",
